def parser(log: str) -> dict[str, str]:
    import json
    import re
    import xml.etree.ElementTree as ET

    results: dict[str, str] = {}
    rank = {"pass": 1, "skip": 2, "fail": 3}

    def set_status(name: str, status: str) -> None:
        if not name:
            return
        status = status.lower()
        if status not in rank:
            return
        prev = results.get(name)
        if prev is None or rank[status] > rank[prev]:
            results[name] = status

    def prefix(pkg: str, test: str) -> str:
        if not pkg:
            return test
        pkg = pkg.rstrip("/")
        if test.startswith(pkg + "/"):
            return test
        return f"{pkg}/{test}"

    go_re = re.compile(r"---\s+(PASS|FAIL|SKIP):\s+([^\s(]+)")
    pytest_re = re.compile(r"^(\S+?::\S+)\s+(PASSED|FAILED|SKIPPED|ERROR|XFAIL|XPASS)\b")
    unittest_re = re.compile(r"^(\w[\w\.]*?)\s+\.\.\.\s+(ok|FAIL|ERROR|skipped)\b", re.I)
    jest_re = re.compile(r"^\s*([✓✕○])\s+(.+?)(?:\s+\(|$)")
    generic_re = re.compile(r"^(PASS|FAIL|SKIP)\s+(.+)$")

    def parse_text(text: str, pkg: str | None = None) -> None:
        for line in text.splitlines():
            line = line.rstrip("\n")
            if not line:
                continue

            m = go_re.search(line)
            if m:
                status = {"PASS": "pass", "FAIL": "fail", "SKIP": "skip"}[m.group(1)]
                name = m.group(2)
                set_status(prefix(pkg or "", name), status)
                continue

            m = pytest_re.search(line)
            if m:
                name = m.group(1)
                status_raw = m.group(2)
                if status_raw == "PASSED":
                    status = "pass"
                elif status_raw in ("SKIPPED", "XFAIL"):
                    status = "skip"
                else:
                    status = "fail"
                set_status(prefix(pkg or "", name), status)
                continue

            m = unittest_re.search(line)
            if m:
                name = m.group(1)
                status_raw = m.group(2).lower()
                if status_raw == "ok":
                    status = "pass"
                elif status_raw == "skipped":
                    status = "skip"
                else:
                    status = "fail"
                set_status(prefix(pkg or "", name), status)
                continue

            m = jest_re.search(line)
            if m:
                symbol, name = m.group(1), m.group(2).strip()
                status = {"✓": "pass", "✕": "fail", "○": "skip"}.get(symbol)
                if status:
                    set_status(prefix(pkg or "", name), status)
                continue

            m = generic_re.search(line)
            if m:
                status = m.group(1).lower()
                name = m.group(2).strip()
                set_status(prefix(pkg or "", name), status)

    raw_lines: list[str] = []
    for line in log.splitlines():
        if not line.strip():
            continue
        try:
            entry = json.loads(line)
        except json.JSONDecodeError:
            raw_lines.append(line)
            continue

        action = entry.get("Action")
        test = entry.get("Test")
        pkg = (entry.get("Package") or "").strip()

        if action in ("pass", "fail", "skip") and test:
            set_status(prefix(pkg, test), action)

        output = entry.get("Output")
        if output:
            parse_text(output, pkg)

    if raw_lines:
        parse_text("\n".join(raw_lines), None)

    # Parse any embedded JUnit XML
    if "<testsuite" in log or "<testcase" in log:
        segments = re.findall(r"<testsuites[^>]*>.*?</testsuites>", log, re.S)
        if not segments:
            segments = re.findall(r"<testsuite[^>]*>.*?</testsuite>", log, re.S)
        for seg in segments:
            try:
                root = ET.fromstring(seg)
            except ET.ParseError:
                continue
            suites = []
            if root.tag == "testsuite":
                suites = [root]
            elif root.tag == "testsuites":
                suites = list(root.findall(".//testsuite"))
            for suite in suites:
                for tc in suite.findall(".//testcase"):
                    name = tc.get("name")
                    classname = tc.get("classname")
                    full = f"{classname}.{name}" if classname else name
                    status = "pass"
                    if tc.find("failure") is not None or tc.find("error") is not None:
                        status = "fail"
                    elif tc.find("skipped") is not None:
                        status = "skip"
                    set_status(full, status)

    return results
